import * as shopifyCart from '@shopify/theme-cart';
import { getElement } from '../utils/functional';
import { Module } from './module/module'; // eslint-disable-next-line import/no-default-export

export default class _class extends Module {
  setupListeners() {
    super.setupListeners();
    this.listeners.add(this.element, 'click', this.onRemoveClick);
    this.listeners.add(this.element, 'click', this.onUpdateClick);
  }

  async onRemoveClick(e) {
    if (e.target.closest(this.selectors.remove) == null) return;
    const lineItem = new LineItem(e.target.closest(this.selectors.item), this);
    await this.render(await lineItem.remove());
  }

  async onUpdateClick(e) {
    if (e.target.closest(this.selectors.update) == null) return;
    const lineItem = new LineItem(e.target.closest(this.selectors.item), this);
    await this.render(await lineItem.update({
      quantity: lineItem.quantity
    }));
  }

  async render(state) {
    if (state.item_count === 0) return window.location.reload();
    await Promise.all([this.renderCartItems(), this.renderCartSummary()]).then(([cartItemsHtml, cartSummaryHtml]) => {
      this.itemsContainerEl.innerHTML = cartItemsHtml;
      this.summaryContainerEl.innerHTML = cartSummaryHtml;
      window.BAO.application.reinitialiseModules(this.itemsContainerEl);
      window.BAO.application.reinitialiseModules(this.summaryContainerEl);
    });
    this.renderCartCounts(state.item_count);
  }

  renderCartItems() {
    return fetch("/?section_id=cart-items").then(res => res.text());
  }

  renderCartSummary() {
    return fetch("/?section_id=cart-summary").then(res => res.text());
  }

  renderCartCounts(count) {
    this.countEls.forEach(el => el.textContent = count);
  }

}
_class.methods = ['onRemoveClick', 'onUpdateClick'];
_class.targets = ['itemsContainer', 'summaryContainer', 'item', 'remove', 'update', 'count'];

class LineItem {
  constructor(item, module) {
    this.item = item;
    this.module = module;
  }

  async remove() {
    return shopifyCart.removeItem(this.key);
  }

  async update(options) {
    return shopifyCart.updateItem(this.key, options);
  }

  get key() {
    return this.item.dataset.key;
  }

  get quantity() {
    return parseInt(getElement("[name=\"crt-Product_Quantity\"]", {
      context: this.item
    }).value, 10);
  }

}